const D = { energy:.62, density:.5, alpha:.9, refract:.55, fog:.28, speed:1, scale:1, hue:205, x:.5, y:.5, style:'rain', act:'bead', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,v)=>{h=((h%360)+360)%360;s/=100;v/=100;const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,b;const sg=Math.floor(h/60)%6;if(sg===0){r=c;g=x;b=0;}else if(sg===1){r=x;g=c;b=0;}else if(sg===2){r=0;g=c;b=x;}else if(sg===3){r=0;g=x;b=c;}else if(sg===4){r=x;g=0;b=c;}else{r=c;g=0;b=x;}return [((r+m)*255)|0,((g+m)*255)|0,((b+m)*255)|0];};
const rgba=(c,a)=>`rgba(${c[0]},${c[1]},${c[2]},${clp(a,0,1).toFixed(4)})`;
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H),t=K.t,key=W+'x'+H,dc=drawingContext;

// ---- a coarse copy of the scene to refract through each bead
if(!S.cap||S.key!==key){
  let cw,ch;
  if(W>=H){ cw=340; ch=Math.max(24,Math.round(340*H/W)); } else { ch=340; cw=Math.max(24,Math.round(340*W/H)); }
  if(S.cap&&S.cap.remove)S.cap.remove();
  S.cap=createGraphics(cw,ch); S.cap.pixelDensity(1); S.capEl=S.cap.elt||S.cap.canvas;
  S.key=key;
}
const cap=S.cap, cw=cap.width, ch=cap.height, kx=cw/W, ky=ch/H;
cap.clear(); cap.drawingContext.drawImage(dc.canvas,0,0,cw,ch);

const en=clp(P.energy,0,1);
const sp=0.45+clp(P.speed,.15,4)*0.55;
const style=P.style, hue=((P.hue%360)+360)%360, alpha=clp(P.alpha,0,1);
const isSchem=style==='schematic', isCond=style==='condensation', isMacro=style==='macro';

// ---- act: multi-minute programs
let runMul=1, fogMul=1, nMul=1;
if(P.act==='squall'){ runMul=1+1.6*Math.pow(0.5+0.5*Math.sin(t*0.038*sp),3)+0.6*A.bass; fogMul=0.8; }
else if(P.act==='clearing'){ const c=0.5+0.5*Math.sin(t*0.021*sp); fogMul=0.25+1.5*c; nMul=0.45+0.75*c; }

const n=Math.max(3,Math.round((isMacro?4:16)+clp(P.density,0,1)*(isMacro?9:56)*nMul));
const refr=clp(P.refract,0,1);
const mag=1.4+refr*2.6;
const litA=(Math.PI*1.15)+0.30*Math.sin(t*0.047*sp);   // key direction, slowly turning

// ---- 1. breath fog: a veil with the beads' own clear haloes punched out later
const fogA=clp(clp(P.fog,0,1)*fogMul*(0.5+0.6*en),0,0.85);
if(fogA>0.01 && !isSchem){
  const fc=isCond?hsb2rgb(hue-20,12,92):hsb2rgb(hue,16,80);
  dc.fillStyle=rgba(fc,fogA*0.30*alpha); dc.fillRect(0,0,W,H);
}

// ---- 2. runnels: the trail a sliding bead leaves behind it
// (drawn before the beads so each bead sits on the head of its own track)
if(!isSchem){
  for(let i=0;i<n;i++){
    const big=fr(i*13+2);
    const rate=(0.002+0.105*big*big*big)*sp*(0.45+0.55*fr(i*17+6))*runMul;
    if(rate<0.02) continue;
    const r=u*(0.010+0.055*big*big)*Math.max(0.3,P.scale)*(isMacro?2.1:1);
    const yy=(md(fr(i*7+1)+t*rate,1.24)-0.12)*H;
    const xx=(fr(i*5+3)+Math.sin(t*(0.09+0.13*fr(i*19+7))*sp+i)*0.012*(0.3+big))*W;
    const len=clp(rate*H*3.4,0,H*0.42);
    const g=dc.createLinearGradient(xx,yy-len,xx,yy);
    const rc=hsb2rgb(hue,22,72);
    g.addColorStop(0,rgba(rc,0)); g.addColorStop(1,rgba(rc,0.16*en*alpha));
    dc.fillStyle=g; dc.fillRect(xx-r*0.42,yy-len,r*0.84,len);
  }
}

// ---- 3. the beads. Each is a lens: it shows the scene behind it inverted and magnified.
for(let i=0;i<n;i++){
  const big=fr(i*13+2);
  const r=Math.max(1.2,u*(0.010+0.055*big*big)*Math.max(0.3,P.scale)*(isMacro?2.1:1)*(isCond?0.62:1));
  const rate=(0.002+0.105*big*big*big)*sp*(0.45+0.55*fr(i*17+6))*runMul;
  const yy=(md(fr(i*7+1)+t*rate,1.24)-0.12)*H+(P.y-0.5)*H*0.05;
  const xx=(fr(i*5+3)+Math.sin(t*(0.09+0.13*fr(i*19+7))*sp+i)*0.012*(0.3+big))*W+(P.x-0.5)*W*0.05;
  if(yy<-r||yy>H+r) continue;
  const sq=1+0.16*Math.min(1,rate*7);      // faster beads elongate
  if(isSchem){
    dc.strokeStyle=rgba(hsb2rgb(196,58,88),(0.30+0.45*big)*alpha);
    dc.lineWidth=Math.max(0.8,u*0.0012);
    dc.beginPath(); dc.ellipse(xx,yy,r,r*sq,0,0,TAU); dc.stroke();
    dc.beginPath(); dc.moveTo(xx-r,yy-r*0.35); dc.lineTo(xx+r,yy+r*0.35); dc.stroke();
    dc.beginPath(); dc.moveTo(xx,yy-r*sq); dc.lineTo(xx,yy+r*sq); dc.stroke();
    continue;
  }
  // refracted interior
  if(refr>0.02){
    const sHalf=r/mag;
    let sx=(xx-sHalf)*kx, sy=(yy-sHalf)*ky, sw=Math.max(1,2*sHalf*kx), sh=Math.max(1,2*sHalf*ky);
    sx=clp(sx,0,Math.max(0,cw-sw)); sy=clp(sy,0,Math.max(0,ch-sh));
    dc.save();
    dc.beginPath(); dc.ellipse(xx,yy,r,r*sq,0,0,TAU); dc.clip();
    dc.translate(xx,yy); dc.scale(-1,-1); dc.translate(-xx,-yy);   // a lens inverts
    dc.drawImage(S.capEl,sx,sy,sw,sh,xx-r,yy-r*sq,r*2,r*sq*2);
    dc.restore();
  }
  // the read on ANY scene, however dark: a refracting edge, a specular hit, a lit lower rim
  const gx=Math.cos(litA), gy=Math.sin(litA);
  dc.strokeStyle=rgba(hsb2rgb(hue,52,6),(0.30+0.28*en)*alpha);
  dc.lineWidth=Math.max(0.7,r*0.16);
  dc.beginPath(); dc.ellipse(xx,yy,r*0.94,r*sq*0.94,0,0,TAU); dc.stroke();
  dc.strokeStyle=rgba(hsb2rgb(hue,10,100),(0.36+0.44*en)*alpha);
  dc.lineWidth=Math.max(0.6,r*0.13);
  dc.beginPath(); dc.ellipse(xx,yy,r*0.86,r*sq*0.86,0,0.7,2.55); dc.stroke();
  dc.fillStyle=rgba(hsb2rgb(hue,6,100),(0.55+0.4*en)*alpha);
  dc.beginPath(); dc.ellipse(xx-gx*r*0.42,yy-gy*r*0.42,r*0.20,r*0.14,litA,0,TAU); dc.fill();
  if(big>0.5){
    dc.fillStyle=rgba(hsb2rgb(hue,14,100),(0.20+0.24*en)*alpha);
    dc.beginPath(); dc.ellipse(xx+gx*r*0.40,yy+gy*r*0.46,r*0.30,r*0.13,litA,0,TAU); dc.fill();
  }
}

// ---- 4. condensation: a dense micro-dew that shimmers on its own slow clock
if(isCond&&!isSchem){
  const nd=Math.round(60+clp(P.density,0,1)*140);
  dc.globalCompositeOperation='lighter';
  const dcol=hsb2rgb(hue,10,100);
  for(let i=0;i<nd;i++){
    const dx=(fr(i*31+11)+Math.sin(t*0.031*sp+i*0.7)*0.004)*W;
    const dy=md(fr(i*37+12)+t*0.0035*sp*(0.4+fr(i*41)),1.1)*H-H*0.05;
    const dr=Math.max(0.6,u*0.0022*(0.4+fr(i*43+13))*Math.max(0.3,P.scale));
    dc.fillStyle=rgba(dcol,(0.10+0.30*fr(i*47+14))*en*alpha);
    dc.beginPath(); dc.arc(dx,dy,dr,0,TAU); dc.fill();
  }
  dc.globalCompositeOperation='source-over';
}

dc.globalAlpha=1; dc.globalCompositeOperation='source-over';
blendMode(BLEND); dc.shadowBlur=0; noStroke();
